    /**
     * Tests getting all VerifiedAddresss.
     *
     * @return    Collection
     */
    public List<VerifiedAddress> testGetAll() throws Throwable {
    LOGGER.info( "VerifiedAddressTest:testGetAll() - Retrieving Collection of VerifiedAddresss:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all VerifiedAddress : " );
    List<VerifiedAddress> collection  = null;

    try {
        // call the static get method on the VerifiedAddressService
        collection = service.getAllVerifiedAddress();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            VerifiedAddress currEntity  = null;
            Iterator<VerifiedAddress> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getVerifiedAddressId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

